// NOTE: same code as ACarryableUnit::Create (004d7c40), folded in retail
TBOOL AUnitPoolBfa::Create( AUnitTransform* a_pTransform )
{
	if ( !AAnimatedUnit::Create( a_pTransform ) )
		return TFALSE;

	m_eFlags |= FLAGS_AI_ENABLED;
	m_eFlags |= FLAGS_AI_ENABLED | FLAGS_THINK_ENABLED;

	return TTRUE;
}

// $Barnyard: FUNCTION 004d7c70
void AUnitPoolBfa::UpdateAI( TFLOAT a_fDeltaTime )
{
	ASteer* pSteer = m_pSteer;
	GetAnimatableObject()->GetModelInstance()->SetTransform( *pSteer->GetPosition(), m_vecDirection );

	AVisibleUnit::UpdateAI( a_fDeltaTime );
}

// $Barnyard: FUNCTION 004d7ae0
// NOTE: a thunk to AVisibleUnit::Think shared by several classes in retail
TBOOL AUnitPoolBfa::Think( TFLOAT a_fDeltaTime )
{
	return AVisibleUnit::Think( a_fDeltaTime );
}
